import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 37 The process of ageing","description":"学习 比较级重复与渐变表达，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 37 The process of ageing","description":"学习 比较级重复与渐变表达，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 比较级重复与渐变表达，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 36 The cost of government","link":"/life/english/new-concept/book-4/unit-05/lesson-036"},"next":{"text":"第四册：流利英语 · Lesson 38 Water and the traveller","link":"/life/english/new-concept/book-4/unit-05/lesson-038"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 36 The cost of government","link":"/life/english/new-concept/book-4/unit-05/lesson-036"},"next":{"text":"第四册：流利英语 · Lesson 38 Water and the traveller","link":"/life/english/new-concept/book-4/unit-05/lesson-038"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-037.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-037.md"}'),r={name:"life/english/new-concept/book-4/unit-05/lesson-037.md"};function i(l,e,s,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-37-the-process-of-ageing" tabindex="-1">第四册：流利英语 · Lesson 37 The process of ageing <a class="header-anchor" href="#第四册-流利英语-·-lesson-37-the-process-of-ageing" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 37 The process of ageing&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过衰老过程这一科普主题练习描述渐进变化和研究限制。区分群体平均变化与个体经历，不把年龄单独当成解释一切差异的原因。重点使用越发、逐渐和比较级重复结构，准确说明变化方向，同时避免暗示某趋势对每个人都以同一速度发生。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>process</td><td>/ˈprəʊses/</td><td>n.</td><td>过程</td><td>a gradual process</td></tr><tr><td>variation</td><td>/ˌveəriˈeɪʃən/</td><td>n.</td><td>差异</td><td>individual variation</td></tr><tr><td>gradual</td><td>/ˈɡrædʒuəl/</td><td>adj.</td><td>逐渐的</td><td>a gradual change</td></tr><tr><td>capacity</td><td>/kəˈpæsəti/</td><td>n.</td><td>能力；容量</td><td>storage capacity</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>over the course of — 在某段时间过程中</li><li>at different rates — 以不同速度</li></ul><h2 id="语法讲解-比较级重复与渐变表达" tabindex="-1">语法讲解：比较级重复与渐变表达 <a class="header-anchor" href="#语法讲解-比较级重复与渐变表达" aria-label="Permalink to &quot;语法讲解：比较级重复与渐变表达&quot;">​</a></h2><p>形容词比较级 + and + 比较级表示越来越，如 slower and slower；多音节形容词用 more and more complex，不写 more complex and complex。increasingly + 形容词可作较紧凑表达。该结构只给出变化方向，不给变化速度、起点或适用范围。讨论群体研究时应补充 in this sample、over five years 等限定；趋势不意味着所有个体同步变化。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The records became more and more detailed over the course of the study.</p></blockquote><p>研究过程中，记录变得越来越详细。</p><p>more and more detailed 表渐变程度；over the course of… 限定变化发生的时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>more and more better 不成立；better 已是比较级，应写 better and better。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 more and more 读成递进节奏，但不加速吞掉第二个 more；在 different patterns 上重读，体现差异。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our records became more and more detailed during the five-year project. Participants showed different patterns of change. We should describe that variation rather than rely on one average alone.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构长期研究笔记，谈资料变化和个体差异，不作医疗建议。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>将长期观察与统计概括区分，强调平均值不能替代个体分布。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改错：The descriptions became more and more clearer.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The descriptions became clearer and clearer.</p><p><strong>解析：</strong> clearer 已为比较级，不能再加 more。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>用 increasingly 改写 more and more detailed。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> increasingly detailed</p><p><strong>解析：</strong> increasingly 修饰原级形容词 detailed。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例能说明每份记录改善速度相同吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 渐变结构没有提供个体速度信息。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：比较级重复与渐变表达。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-038">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
